### 3. popup.js

```javascript
document.addEventListener('DOMContentLoaded', function() {
  const saveButton = document.getElementById('savePage');
  const statusDiv = document.getElementById('status');

  saveButton.addEventListener('click', async () => {
    try {
      statusDiv.textContent = 'Saving...';

      // Get the current tab
      const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });

      // Execute script to get page contents
      const results = await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        function: getPageContents
      });

      const pageData = results[0].result;

      // Save the data
      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      const filename = `saved-page-${timestamp}.html`;

      // Create a blob with the HTML content
      const blob = new Blob([pageData.html], { type: 'text/html' });
      const url = URL.createObjectURL(blob);

      // Download the file
      chrome.downloads.download({
        url: url,
        filename: filename,
        saveAs: true
      });

      statusDiv.textContent = 'Page saved successfully!';
      setTimeout(() => statusDiv.textContent = '', 2000);
    } catch (error) {
      console.error('Error saving page:', error);
      statusDiv.textContent = 'Error saving page.';
      setTimeout(() => statusDiv.textContent = '', 2000);
    }
  });
});

// This function will be injected into the page
function getPageContents() {
  return {
    url: window.location.href,
    title: document.title,
    html: document.documentElement.outerHTML
  };
}
