/**
 * Processes command line arguments to set windowed/fullscreen mode.
 * @param args The command line argument string to process
 */
void handleCmdLineArgs(char *args)
{
    size_t argLength = 0;
    int currentPos = 0;
    unsigned int sjisCheckResult = 0;
    char *currentCharPtr = args;

    // Calculate the length of the argument string
    size_t maxLength = (size_t)-1;  // Initialize with maximum possible size
    do {
        if (maxLength == 0) break;
        maxLength--;
    } while (*currentCharPtr++ != '\0');

    size_t actualLength = ~maxLength - 1;  // Equivalent to strlen

    // Only process if we have arguments (length > 2)
    if (actualLength > 2) {
        while (currentPos < actualLength - 1) {
            // Check if current character is part of a Shift-JIS sequence
            sjisCheckResult = RK_CheckSJIS(sjisCheckResult & 0xFFFFFF00 | (unsigned char)args[currentPos]);

            if (sjisCheckResult == 1) {
                currentPos++;  // Skip next byte for SJIS
            }
            else if (args[currentPos] == '/') {
                // Check for windowed/fullscreen flag
                char nextChar = args[currentPos + 1] | 0x20;  // Convert to lowercase

                if (nextChar == 'w') {
                    IsWindowedMode = 1;  // Enable windowed mode
                }
                else if (nextChar == 'f') {
                    IsWindowedMode = 0;  // Enable fullscreen mode
                }
            }

            currentPos++;
        }
    }
}
