# Calculating Pi in JavaScript

Here are several JavaScript methods to calculate the value of π (pi) with increasing precision:

## 1. Simple Approximation (Gregory-Leibniz Series)
```javascript
function calculatePiLeibniz(iterations) {
    let pi = 0;
    let denominator = 1;

    for (let i = 0; i < iterations; i++) {
        if (i % 2 === 0) {
            pi += 4 / denominator;
        } else {
            pi -= 4 / denominator;
        }
        denominator += 2;
    }

    return pi;
}

console.log(calculatePiLeibniz(1000000)); // Approximates π (slow convergence)
```

## 2. Better Convergence (Nilakantha Series)
```javascript
function calculatePiNilakantha(iterations) {
    let pi = 3;
    let denominator = 2;
    let operation = 1;

    for (let i = 0; i < iterations; i++) {
        pi += operation * (4 / (denominator * (denominator + 1) * (denominator + 2)));
        operation *= -1;
        denominator += 2;
    }

    return pi;
}

console.log(calculatePiNilakantha(100)); // More efficient than Leibniz
```

## 3. Fastest Algorithm (Chudnovsky Algorithm)
```javascript
function calculatePiChudnovsky(digits) {
    // Set precision needed
    if (digits > 15) digits = 15; // JavaScript number precision limit

    const C = 426880 * Math.sqrt(10005);
    let sum = 0;
    const K = 6;
    const M = 1;
    const L = 13591409;
    const X = 1;
    let L_val = L;
    let X_val = X;

    for (let k = 0; k < digits; k++) {
        const M_val = (K*k - 5) * (K*k - 4) * (K*k - 3) * (K*k - 2) * (K*k - 1) * (K*k);
        if (k > 0) M_val /= Math.pow(k, 6);

        sum += (M * L_val) / X_val;
        L_val += 545140134;
        X_val *= -262537412640768000;
    }

    return C / sum;
}

console.log(calculatePiChudnovsky(15)); // Very accurate but complex
```

## 4. Using JavaScript's Built-in Math.PI
```javascript
console.log(Math.PI); // Most precise built-in value
```

Notes:
1. The Leibniz and Nilakantha series are simple but converge slowly.
2. The Chudnovsky algorithm is much faster but more complex.
3. JavaScript's number precision is limited to about 15 decimal digits.
4. For higher precision, you would need to use arbitrary-precision libraries.

