```javascript
// Initialize the chat
const chatContainer = document.getElementById('chat-container');
const userInput = document.getElementById('user-input');
const sendBtn = document.getElementById('send-btn');

// Add a message to the chat
function addMessage(text, isUser = false) {
    const messageDiv = document.createElement('div');
    messageDiv.classList.add('message');
    messageDiv.classList.add(isUser ? 'user-message' : 'bot-message');
    messageDiv.textContent = text;
    chatContainer.appendChild(messageDiv);
    chatContainer.scrollTop = chatContainer.scrollHeight;
}

// Initialize the model
let pipeline;
let isModelReady = false;

async function initializeModel() {
    addMessage("Loading BlenderBot model... Please wait.", false);

    try {
        // Import the pipeline function from transformers.js
        const { pipeline } = await import('https://cdn.jsdelivr.net/npm/@xenova/transformers@2.4.0');

        // Create a conversational pipeline with the BlenderBot model
        pipeline = await pipeline('conversational', 'facebook/blenderbot-400M-distill', {
            progress_callback: (progress) => {
                if (progress.status === 'progress') {
                    const percent = Math.round(progress.progress * 100);
                    const loadingMessage = document.querySelector('.loading');
                    if (loadingMessage) {
                        loadingMessage.textContent = `Loading model: ${percent}%`;
                    } else {
                        addMessage(`Loading model: ${percent}%`, false);
                        chatContainer.lastChild.classList.add('loading');
                    }
                }
            }
        });

        isModelReady = true;
        addMessage("Model loaded! How can I help you today?", false);
        sendBtn.disabled = false;
    } catch (error) {
        console.error('Error loading model:', error);
        addMessage("Failed to load the model. Please check the console for details.", false);
    }
}

// Handle user input
async function handleUserInput() {
    const text = userInput.value.trim();
    if (!text || !isModelReady) return;

    // Add user message to chat
    addMessage(text, true);
    userInput.value = '';
    sendBtn.disabled = true;

    // Show typing indicator
    const typingIndicator = document.createElement('div');
    typingIndicator.classList.add('message', 'bot-message');
    typingIndicator.textContent = "Thinking...";
    chatContainer.appendChild(typingIndicator);
    chatContainer.scrollTop = chatContainer.scrollHeight;

    try {
        // Generate response
        const response = await pipeline(text);

        // Remove typing indicator
        chatContainer.removeChild(typingIndicator);

        // Add bot response
        addMessage(response.generated_text, false);
    } catch (error) {
        console.error('Error generating response:', error);
        chatContainer.removeChild(typingIndicator);
        addMessage("Sorry, I encountered an error. Please try again.", false);
    } finally {
        sendBtn.disabled = false;
        userInput.focus();
    }
}

// Event listeners
sendBtn.addEventListener('click', handleUserInput);
userInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
        handleUserInput();
    }
});

// Disable send button until model is ready
sendBtn.disabled = true;

// Initialize the model when the page loads
window.addEventListener('DOMContentLoaded', initializeModel);
```

## Features of this Implementation:

1. **Vanilla JavaScript**: No frameworks or additional libraries needed
2. **Loading Progress**: Shows model download progress as it loads
