```javascript
document.addEventListener('DOMContentLoaded', function() {
  const container = document.querySelector('.slider-container');
  const slider = document.getElementById('radius-slider');
  const activeCircle = document.getElementById('active-circle');
  const concentricCircles = document.querySelector('.concentric-circles');

  // Create concentric circle markers
  const maxRadius = parseInt(slider.max);
  const steps = 5; // Number of concentric circles
  for (let i = 1; i <= steps; i++) {
    const marker = document.createElement('div');
    marker.className = 'circle-marker';
    const radius = (maxRadius / steps) * i;
    marker.style.width = `${radius * 2}px`;
    marker.style.height = `${radius * 2}px`;
    marker.style.left = '50%';
    marker.style.top = '50%';

    // Add label
    const label = document.createElement('div');
    label.className = 'circle-label';
    label.textContent = `${radius}px`;
    label.style.position = 'absolute';
    label.style.bottom = '-20px';
    label.style.left = '50%';
    label.style.transform = 'translateX(-50%)';
    marker.appendChild(label);

    concentricCircles.appendChild(marker);
  }

  // Update circle when slider changes
