    const radius = parseInt(slider.value);
    activeCircle.style.width = `${radius * 2}px`;
    activeCircle.style.height = `${radius * 2}px`;
    activeCircle.style.left = '50%';
    activeCircle.style.top = '50%';

    // Update display value if you have one
    if (document.getElementById('radius-value')) {
      document.getElementById('radius-value').textContent = radius;
    }
  }

  slider.addEventListener('input', updateCircle);

  // Initialize
  updateCircle();
});
