# PowerShell Script for Two-Way Folder Synchronization on a Domain

Below is a PowerShell script that synchronizes content between two shared folders on different computers within a domain. This script performs a two-way sync, copying new and modified files in both directions.

```powershell
<#
.SYNOPSIS
    Synchronizes content between two shared folders on domain computers.
.DESCRIPTION
    This script performs a two-way synchronization between shared folders on different computers
    within a Windows domain. It handles file creation, updates, and deletions.
.PARAMETER SourcePath
    UNC path to the first shared folder (e.g., \\Computer1\SharedFolder)
.PARAMETER DestinationPath
    UNC path to the second shared folder (e.g., \\Computer2\SharedFolder)
.PARAMETER LogPath
    Path to store synchronization logs (defaults to script directory)
.PARAMETER Credential
    Optional PSCredential object for authentication (if required)
.EXAMPLE
    .\Sync-Folders.ps1 -SourcePath "\\Server1\DepartmentShare" -DestinationPath "\\Server2\DepartmentShare"
.NOTES
    Version: 1.0
    Author: Your Name
    Date:   $(Get-Date -Format "yyyy-MM-dd")
#>

param (
    [Parameter(Mandatory=$true)]
    [string]$SourcePath,

    [Parameter(Mandatory=$true)]
    [string]$DestinationPath,

    [string]$LogPath = "$PSScriptRoot\SyncLogs",

    [System.Management.Automation.PSCredential]$Credential
)

# Function to create a timestamp for logging
function Get-TimeStamp {
    return "[{0:MM/dd/yy} {0:HH:mm:ss}]" -f (Get-Date)
}

# Create log directory if it doesn't exist
if (-not (Test-Path -Path $LogPath)) {
    New-Item -ItemType Directory -Path $LogPath | Out-Null
}

$logFile = Join-Path -Path $LogPath -ChildPath "SyncLog_$(Get-Date -Format 'yyyyMMdd_HHmmss').log"

# Start logging
"$(Get-TimeStamp) Starting folder synchronization between $SourcePath and $DestinationPath" | Out-File -FilePath $logFile -Append

try {
    # Test network connectivity and folder access
    if (-not (Test-Path -Path $SourcePath)) {
        throw "Source path $SourcePath is not accessible"
    }

    if (-not (Test-Path -Path $DestinationPath)) {
        throw "Destination path $DestinationPath is not accessible"
    }

    # Function to sync files from source to destination
    function Sync-Files {
        param (
            [string]$Source,
            [string]$Destination,
            [string]$Direction
        )

        # Get all files from source and destination
        $sourceFiles = Get-ChildItem -Path $Source -Recurse -File
        $destFiles = Get-ChildItem -Path $Destination -Recurse -File

        # Create hashtables for faster lookup
        $sourceHash = @{}
        $destHash = @{}

        foreach ($file in $sourceFiles) {
            $relativePath = $file.FullName.Substring($Source.Length).TrimStart('\')
            $sourceHash[$relativePath] = @{
                'LastWriteTime' = $file.LastWriteTime
                'Length' = $file.Length
            }
        }

        foreach ($file in $destFiles) {
            $relativePath = $file.FullName.Substring($Destination.Length).TrimStart('\')
            $destHash[$relativePath] = @{
                'LastWriteTime' = $file.LastWriteTime
                'Length' = $file.Length
            }
        }

        # Sync new and modified files from source to destination
        foreach ($key in $sourceHash.Keys) {
            $sourceFile = Join-Path -Path $Source -ChildPath $key
            $destFile = Join-Path -Path $Destination -ChildPath $key

            if (-not $destHash.ContainsKey($key)) {
                # File exists in source but not in destination - copy it
                $destDir = [System.IO.Path]::GetDirectoryName($destFile)

                if (-not (Test-Path -Path $destDir)) {
                    New-Item -Path $destDir -ItemType Directory -Force | Out-Null
                    "$(Get-TimeStamp) Created directory: $destDir ($Direction)" | Out-File -FilePath $logFile -Append
                }

                Copy-Item -Path $sourceFile -Destination $destFile -Force
                "$(Get-TimeStamp) Copied new file: $sourceFile to $destFile ($Direction)" | Out-File -FilePath $logFile -Append
            }
            else {
                # File exists in both locations - check if source is newer
                $sourceModified = $sourceHash[$key].LastWriteTime
                $destModified = $destHash[$key].LastWriteTime

                if ($sourceModified -gt $destModified) {
                    Copy-Item -Path $sourceFile -Destination $destFile -Force
                    "$(Get-TimeStamp) Updated file: $destFile with newer version from $sourceFile ($Direction)" | Out-File -FilePath $logFile -Append
                }
                elseif ($sourceModified -ne $destModified -and $sourceHash[$key].Length -eq $destHash[$key].Length) {
                    # If timestamps differ but file sizes match, set the same timestamp
                    (Get-Item $destFile).LastWriteTime = $sourceModified
                }
            }
        }

        # Delete files from destination that don't exist in source
        foreach ($key in $destHash.Keys) {
            if (-not $sourceHash.ContainsKey($key)) {
                $fileToDelete = Join-Path -Path $Destination -ChildPath $key
                Remove-Item -Path $fileToDelete -Force
                "$(Get-TimeStamp) Deleted file: $fileToDelete (no longer exists in source $Direction)" | Out-File -FilePath $logFile -Append
            }
        }

        # Sync directory structure (create missing directories in destination)
        $sourceDirs = Get-ChildItem -Path $Source -Recurse -Directory
        foreach ($dir in $sourceDirs) {
            $relativePath = $dir.FullName.Substring($Source.Length).TrimStart('\')
            $destDir = Join-Path -Path $Destination -ChildPath $relativePath

            if (-not (Test-Path -Path $destDir)) {
                New-Item -Path $destDir -ItemType Directory -Force | Out-Null
                "$(Get-TimeStamp) Created directory: $destDir ($Direction)" | Out-File -FilePath $logFile -Append
            }
        }

        # Remove empty directories from destination that don't exist in source
        $destDirs = Get-ChildItem -Path $Destination -Recurse -Directory | Sort-Object -Property FullName -Descending
        foreach ($dir in $destDirs) {
            $relativePath = $dir.FullName.Substring($Destination.Length).TrimStart('\')
            $sourceDir = Join-Path -Path $Source -ChildPath $relativePath

            if (-not (Test-Path -Path $sourceDir)) {
                # Check if directory is empty
                if ((Get-ChildItem -Path $dir.FullName -Force).Count -eq 0) {
                    Remove-Item -Path $dir.FullName -Force -Recurse
                    "$(Get-TimeStamp) Removed empty directory: $($dir.FullName) (no longer exists in source $Direction)" | Out-File -FilePath $logFile -Append
                }
            }
        }
    }

    # Perform sync in both directions
    Sync-Files -Source $SourcePath -Destination $DestinationPath -Direction "Source → Destination"
    Sync-Files -Source $DestinationPath -Destination $SourcePath -Direction "Destination → Source"

    "$(Get-TimeStamp) Synchronization completed successfully" | Out-File -FilePath $logFile -Append
}
catch {
    "$(Get-TimeStamp) ERROR: $_" | Out-File -FilePath $logFile -Append
    throw $_
}
finally {
    "$(Get-TimeStamp) Synchronization process ended" | Out-File -FilePath $logFile -Append
}
```

## How to Use This Script

1. Save the script as `Sync-Folders.ps1`
2. Run it with PowerShell, providing the UNC paths to your shared folders:
   ```
   .\Sync-Folders.ps1 -SourcePath "\\Computer1\SharedFolder" -DestinationPath "\\Computer2\SharedFolder"
   ```
3. If authentication is required, use the `-Credential` parameter with a PSCredential object.

## Features

