- For large folders, the initial sync may take significant time
- Consider testing with a small set of files first
- The script preserves file timestamps during synchronization

# Handling Blocking Read Interrupted by Signal (EINTR Example)

Here's a complete example demonstrating how to properly handle a blocking read operation that gets interrupted by a signal (EINTR):

```c
#include <stdio.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

// Signal handler
void sig_handler(int signo) {
    printf("\nReceived signal %d\n", signo);
}

int main() {
    char buf[256];
    ssize_t n;

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    printf("Waiting for input (press Ctrl+C to interrupt)...\n");

    while (1) {
        n = read(STDIN_FILENO, buf, sizeof(buf) - 1);

        if (n == -1) {
            if (errno == EINTR) {
                // Operation was interrupted by signal
                printf("Read was interrupted by signal, retrying...\n");
                continue;
            } else {
                // Other error occurred
                perror("read");
                return 1;
            }
        } else if (n == 0) {
            // EOF (e.g., if input was redirected from a file)
            printf("End of input\n");
            break;
        } else {
            // Success
            buf[n] = '\0';
            printf("Read %zd bytes: %s", n, buf);
            break;
        }
    }

    return 0;
}
```

## Key Points:

1. **EINTR Handling**: The code checks for `errno == EINTR` when `read()` returns -1, which means the system call was interrupted by a signal before any data was read.

2. **Proper Loop Structure**: The read operation is wrapped in a loop that will retry when interrupted.

3. **Signal Setup**: The program sets up a signal handler for SIGINT (Ctrl+C) to demonstrate the interruption.

4. **Other Error Handling**: Also handles other error cases and EOF condition properly.

5. **Thread Safety**: In a multi-threaded program, you'd want to use `sigaction` with `SA_RESTART` flag for automatic restart of system calls, but this example shows the manual handling approach which gives you more control.

When you run this program and press Ctrl+C while it's waiting for input, you'll see it handle the interruption gracefully and continue waiting for input.

# C++ Code to Read Network Packets from a Socket on Port 888

Here's a complete C++ program that creates a socket, binds it to port 888, and reads incoming network packets:

```cpp
#include <iostream>
#include <string>
#include <cstring>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <arpa/inet.h>

const int PORT = 888;
const int BUFFER_SIZE = 4096; // Buffer size for incoming packets

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Forcefully attaching socket to the port 888
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind the socket to port 888
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    std::cout << "Server listening on port " << PORT << std::endl;

    // Accept incoming connection
    if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
        perror("accept");
        exit(EXIT_FAILURE);
    }

    char client_ip[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &(address.sin_addr), client_ip, INET_ADDRSTRLEN);
    std::cout << "Connection accepted from " << client_ip << ":" << ntohs(address.sin_port) << std::endl;

    // Read incoming data
    while (true) {
        int bytes_read = read(new_socket, buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            perror("read");
            break;
        } else if (bytes_read == 0) {
            std::cout << "Client disconnected" << std::endl;
            break;
        }

        std::cout << "Received " << bytes_read << " bytes: ";
        // Print the first few characters (for demonstration)
        for (int i = 0; i < std::min(bytes_read, 16); i++) {
            if (isprint(buffer[i])) {
                std::cout << buffer[i];
            } else {
                printf("\\x%02x", (unsigned char)buffer[i]);
            }
        }
        std::cout << std::endl;

        // Clear buffer for next read
        memset(buffer, 0, BUFFER_SIZE);
    }

    close(new_socket);
    close(server_fd);
    return 0;
}
```

## Notes:

1. This uses TCP (SOCK_STREAM). For UDP (packet-based) communication, you would use SOCK_DGRAM.

2. The code:
   - Creates a socket
   - Binds it to port 888
   - Listens for connections
   - Accepts an incoming connection
   - Reads data from the connection in a loop

3. For a UDP version, you would omit the listen/accept steps and use recvfrom() instead of read().

4. You'll need appropriate permissions to bind to port 888 (ports below 1024 typically require root privileges on Unix-like systems).

5. Error handling is included but could be expanded for production use.

6. The code prints the first 16 bytes of each received packet in both printable and hex format for debugging purposes.

Here's an expression you can add to the Path property of a shape layer in After Effects to create a 500×500 px square with only the top-right corner rounded:

```javascript
// Create a 500x500 square with top-right corner rounded
const width = 500;
const height = 500;
const cornerRadius = 50; // Adjust this value to change the roundness
const halfPI = Math.PI/2;

// Start at top-left corner
var path = [];
path.push([0, 0]);

// Line to just before top-right rounded corner
path.push([width - cornerRadius, 0]);

// Create rounded top-right corner (90° arc)
var center = [width - cornerRadius, cornerRadius];
for (var i = 0; i <= 4; i++) {
    var angle = halfPI * i / 4;
    var x = center[0] + Math.cos(angle) * cornerRadius;
    var y = center[1] - Math.sin(angle) * cornerRadius;
    path.push([x, y]);
}

// Line to bottom-right corner
path.push([width, height]);

// Line to bottom-left corner
path.push([0, height]);

// Close path (back to top-left)
path.push([0, 0]);

// Create the path data
createPath(path, [], []);
```

