### KubernetesClientImpl.java
```java
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.Base64;
import java.util.Map;
import java.util.stream.Collectors;

public class KubernetesClientImpl implements KubernetesClient {
    private final HttpClient httpClient;
    private final KubernetesConfig config;

    public KubernetesClientImpl(KubernetesConfig config) {
        this.config = config;
        this.httpClient = HttpClient.newBuilder()
            .connectTimeout(Duration.ofSeconds(30))
            .version(HttpClient.Version.HTTP_2)
            .build();
    }

    @Override
    public String getPodLogs(String podName) {
        return getPodLogs(podName, Map.of());
    }

    @Override
    public String getPodLogs(String podName, Map<String, String> params) {
        String queryString = params.entrySet().stream()
            .map(entry -> entry.getKey() + "=" + entry.getValue())
            .collect(Collectors.joining("&"));

        String path = String.format("/api/v1/namespaces/%s/pods/%s/log", 
            config.getNamespace(), podName);

        if (!queryString.isEmpty()) {
            path += "?" + queryString;
        }

        HttpRequest request = createAuthenticatedRequest(path);

        try {
            HttpResponse<String> response = httpClient.send(
                request, HttpResponse.BodyHandlers.ofString());

            if (response.statusCode() >= 400) {
                throw new RuntimeException("Failed to get logs: " + response.body());
            }

            return response.body();
        } catch (Exception e) {
            throw new RuntimeException("Error fetching logs", e);
        }
    }

    @Override
    public LogStream streamPodLogs(String podName) {
        // Implementation for streaming logs
        // Would use WebSocket or SSE if available, or chunked HTTP
        throw new UnsupportedOperationException("Streaming not yet implemented");
    }

    @Override
    public void close() {
        // Cleanup resources if needed
    }

    private HttpRequest createAuthenticatedRequest(String path) {
        String url = config.getApiServerUrl() + path;

        return HttpRequest.newBuilder()
            .uri(URI.create(url))
            .header("Authorization", "Bearer " + config.getToken())
            .header("Accept", "application/json")
            .GET()
            .build();
    }
}
```

## 3. Usage Example

```java
public class Main {
    public static void main(String[] args) {
        KubernetesConfig config = new KubernetesConfig()
            .setApiServerUrl("https://kubernetes.default.svc")
            .setNamespace("default")
