# Laravel FavoritesManager and Controller Implementation

I'll help you create a robust `FavoritesManager` class and a corresponding `FavoritesController` that handles both authenticated users and guests.

## FavoritesManager Implementation

```php
<?php

namespace App\Favorites;

use App\Models\User;
use App\Models\Favorite;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\Session;

class FavoritesManager
{
    /**
     * Add a business name to favorites
     *
     * @param string $businessName
     * @return bool
     */
    public function add(string $businessName): bool
    {
        if (Auth::check()) {
            return $this->addToDatabase(Auth::user(), $businessName);
        }

        return $this->addToSession($businessName);
    }

    /**
     * Remove a business name from favorites
     *
     * @param string $businessName
     * @return bool
     */
    public function remove(string $businessName): bool
    {
        if (Auth::check()) {
            return $this->removeFromDatabase(Auth::user(), $businessName);
        }

        return $this->removeFromSession($businessName);
    }

    /**
     * Get all favorite business names
     *
     * @return array
     */
    public function getAll(): array
    {
        if (Auth::check()) {
            return $this->getFromDatabase(Auth::user());
        }

        return $this->getFromSession();
    }

    /**
     * Check if a business name is favorited
     *
     * @param string $businessName
     * @return bool
     */
    public function isFavorite(string $businessName): bool
    {
        if (Auth::check()) {
            return $this->isFavoriteInDatabase(Auth::user(), $businessName);
        }

        return $this->isFavoriteInSession($businessName);
    }

    /**
     * Add to database for authenticated user
     *
     * @param User $user
     * @param string $businessName
     * @return bool
     */
    protected function addToDatabase(User $user, string $businessName): bool
    {
        if (!$this->isFavoriteInDatabase($user, $businessName)) {
            Favorite::create([
                'user_id' => $user->id,
                'business_name' => $businessName
            ]);
            return true;
        }
        return false;
    }

    /**
     * Remove from database for authenticated user
     *
     * @param User $user
     * @param string $businessName
     * @return bool
     */
    protected function removeFromDatabase(User $user, string $businessName): bool
    {
        $deleted = Favorite::where('user_id', $user->id)
            ->where('business_name', $businessName)
            ->delete();

        return $deleted > 0;
    }

    /**
     * Get all favorites from database
     *
     * @param User $user
     * @return array
     */
    protected function getFromDatabase(User $user): array
    {
        return Favorite::where('user_id', $user->id)
            ->pluck('business_name')
            ->toArray();
    }

    /**
     * Check if in database favorites
     *
     * @param User $user
     * @param string $businessName
     * @return bool
     */
    protected function isFavoriteInDatabase(User $user, string $businessName): bool
    {
        return Favorite::where('user_id', $user->id)
            ->where('business_name', $businessName)
            ->exists();
    }

    /**
     * Add to session for guest
     *
     * @param string $businessName
     * @return bool
     */
    protected function addToSession(string $businessName): bool
    {
        $favorites = Session::get('favorites', []);

        if (!in_array($businessName, $favorites)) {
            $favorites[] = $businessName;
            Session::put('favorites', $favorites);
            return true;
        }

        return false;
    }

    /**
     * Remove from session for guest
     *
     * @param string $businessName
     * @return bool
     */
    protected function removeFromSession(string $businessName): bool
    {
        $favorites = Session::get('favorites', []);

        $key = array_search($businessName, $favorites);
        if ($key !== false) {
            unset($favorites[$key]);
            Session::put('favorites', array_values($favorites));
            return true;
        }

        return false;
    }

    /**
     * Get all from session
     *
     * @return array
     */
    protected function getFromSession(): array
    {
        return Session::get('favorites', []);
    }

    /**
     * Check if in session favorites
     *
     * @param string $businessName
     * @return bool
     */
    protected function isFavoriteInSession(string $businessName): bool
    {
        return in_array($businessName, Session::get('favorites', []));
    }

    /**
     * Sync guest favorites to user when they login
     *
     * @param User $user
     * @return void
     */
    public function syncGuestFavoritesToUser(User $user): void
    {
        $guestFavorites = $this->getFromSession();

        if (!empty($guestFavorites)) {
