# Smart Contract Logic for ERC-1155 with Creds Token

Below is a complete smart contract implementation for an ERC-1155 token with special "Creds" functionality. This contract allows for:
- Standard ERC-1155 multi-token functionality
- Special "Creds" tokens with additional features
- Role-based access control
- Customizable creds minting/burning logic

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

contract CredsToken is ERC1155, AccessControl {
    using Strings for uint256;

    // Role definitions
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant BURNER_ROLE = keccak256("BURNER_ROLE");

    // Token IDs
    uint256 public constant CREDS_TOKEN_ID = 0; // Special creds token ID

    // Creds token metadata
    string public name;
    string public symbol;
    string private _baseURI;
    string private _uriSuffix;

    // Mapping for token URIs (for non-creds tokens)
    mapping(uint256 => string) private _tokenURIs;

    // Events
    event CredsMinted(address indexed to, uint256 amount);
    event CredsBurned(address indexed from, uint256 amount);
    event TokenURIUpdated(uint256 tokenId, string newURI);

    constructor(
        string memory _name,
        string memory _symbol,
        string memory baseURI,
        string memory uriSuffix
    ) ERC1155("") {
        name = _name;
        symbol = _symbol;
        _baseURI = baseURI;
        _uriSuffix = uriSuffix;

        // Setup roles
        _setupRole(ADMIN_ROLE, msg.sender);
        _setupRole(MINTER_ROLE, msg.sender);
        _setupRole(BURNER_ROLE, msg.sender);

        // Admin can grant other roles
        _setRoleAdmin(MINTER_ROLE, ADMIN_ROLE);
        _setRoleAdmin(BURNER_ROLE, ADMIN_ROLE);
    }

    /**
     * @dev Returns the URI for a given token ID
     */
    function uri(uint256 tokenId) public view override returns (string memory) {
        if (tokenId == CREDS_TOKEN_ID) {
            return string(abi.encodePacked(_baseURI, "creds", _uriSuffix));
        }

        // For other tokens, use their custom URI if set
        string memory tokenURI = _tokenURIs[tokenId];

        // If no custom URI is set, use the default pattern
        if (bytes(tokenURI).length == 0) {
            return string(abi.encodePacked(_baseURI, tokenId.toString(), _uriSuffix));
        }

        return tokenURI;
    }

    /**
     * @dev Mints creds tokens to an address
     */
    function mintCreds(address to, uint256 amount) public onlyRole(MINTER_ROLE) {
        _mint(to, CREDS_TOKEN_ID, amount, "");
        emit CredsMinted(to, amount);
    }

    /**
     * @dev Burns creds tokens from an address
     */
    function burnCreds(address from, uint256 amount) public onlyRole(BURNER_ROLE) {
        _burn(from, CREDS_TOKEN_ID, amount);
        emit CredsBurned(from, amount);
    }

    /**
     * @dev Mints a new token type (non-creds)
     */
    function mintToken(
        address to,
        uint256 tokenId,
        uint256 amount,
        string memory tokenURI
    ) public onlyRole(MINTER_ROLE) {
        _mint(to, tokenId, amount, "");
        if (bytes(tokenURI).length > 0) {
            _tokenURIs[tokenId] = tokenURI;
            emit TokenURIUpdated(tokenId, tokenURI);
        }
    }

    /**
     * @dev Updates the URI for a non-creds token
     */
    function setTokenURI(uint256 tokenId, string memory newURI) public onlyRole(ADMIN_ROLE) {
        require(tokenId != CREDS_TOKEN_ID, "Cannot change creds token URI");
        _tokenURIs[tokenId] = newURI;
        emit TokenURIUpdated(tokenId, newURI);
    }

    /**
     * @dev Updates the base URI
     */
    function setBaseURI(string memory newBaseURI) public onlyRole(ADMIN_ROLE) {
        _baseURI = newBaseURI;
    }

    /**
     * @dev Updates the URI suffix
     */
    function setURISuffix(string memory newSuffix) public onlyRole(ADMIN_ROLE) {
        _uriSuffix = newSuffix;
    }

    /**
     * @dev Returns the creds balance of an address
     */
    function credsBalance(address account) public view returns (uint256) {
        return balanceOf(account, CREDS_TOKEN_ID);
    }

    /**
     * @dev Checks if an address has sufficient creds
     */
    function hasSufficientCreds(address account, uint256 requiredCreds) public view returns (bool) {
        return balanceOf(account, CREDS_TOKEN_ID) >= requiredCreds;
    }

    /**
     * @dev Override supportsInterface for ERC1155 and AccessControl
     */
    function supportsInterface(bytes4 interfaceId) public view override(ERC1155, AccessControl) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}
```

## Key Features Explained

1. **Creds Token Management**:
   - Special token ID `0` is reserved for creds
   - Dedicated mint/burn functions for creds
   - Easy creds balance checking

2. **Multi-Token Support**:
   - Can mint any number of other token types
   - Custom metadata for each token type

3. **Access Control**:
   - Admin, minter, and burner roles
   - Role-based function restrictions

4. **Metadata Management**:
   - Base URI for all tokens
   - Custom URIs for individual tokens
   - URI suffix for flexibility

## Deployment and Usage

1. Deploy the contract with name, symbol, base URI, and URI suffix
2. Grant roles to appropriate addresses
3. Use `mintCreds` to distribute creds
4. Use `burnCreds` to remove creds when spent
5. Use `mintToken` to create other token types as needed

