      "dst": ["group:nill:*", "group:family:*", "group:servers:*"],
      "proto": "*"
    },

    // family group can only use any node as exit node (but not access services)
    {
      "action": "accept",
      "src": ["group:family"],
      "dst": ["*:*"],
      "proto": "tcp",
      "users": ["autogroup:self"]
    },

    // servers group has access to specific ports on all servers
    {
      "action": "accept",
      "src": ["group:servers"],
      "dst": ["group:nill:22", "group:nill:80", "group:nill:443",
              "group:family:22", "group:family:80", "group:family:443",
              "group:servers:22", "group:servers:80", "group:servers:443"],
      "proto": "tcp"
    },

    // Default deny (implied by Tailscale)
    {
      "action": "accept",
      "src": ["*"],
      "dst": ["*:*"],
      "proto": "*"
    }
  ],
  "ssh": [
    // SSH access rules would go here if needed
  ]
}
```

Key points about this configuration:
1. The `nill` group has unrestricted access to all ports on all machines in all groups
2. The `family` group can only use nodes as exit nodes (via the `autogroup:self` rule) but can't access any services directly
3. The `servers` group can only access ports 22, 80, and 443 on any machine in any group
4. All other access is denied by default (Tailscale's implicit deny)

