# TCP Implementation in TypeScript for IPv4 Payload

Creating a full TCP implementation is complex, but I can provide a basic TypeScript class that can parse and construct TCP segments from an IPv4 packet payload. This implementation will handle the TCP header and basic segment structure.

```typescript
class TCP {
    private data: Uint8Array;

    // TCP header fields
    public sourcePort: number;
    public destinationPort: number;
    public sequenceNumber: number;
    public acknowledgmentNumber: number;
    public dataOffset: number;
    public flags: {
        ns: boolean;
        cwr: boolean;
        ece: boolean;
        urg: boolean;
        ack: boolean;
        psh: boolean;
        rst: boolean;
        syn: boolean;
        fin: boolean;
    };
    public windowSize: number;
    public checksum: number;
    public urgentPointer: number;
    public options?: Uint8Array;
    public payload: Uint8Array;

    constructor(ipv4Payload: Uint8Array) {
        this.data = ipv4Payload;
        this.parseHeader();
    }

    private parseHeader(): void {
        // Minimum TCP header is 20 bytes
        if (this.data.length < 20) {
            throw new Error("TCP segment too short");
        }

        const view = new DataView(this.data.buffer, this.data.byteOffset);

        // Parse header fields
        this.sourcePort = view.getUint16(0);
        this.destinationPort = view.getUint16(2);
        this.sequenceNumber = view.getUint32(4);
        this.acknowledgmentNumber = view.getUint32(8);

        const dataOffsetAndFlags = view.getUint16(12);
        this.dataOffset = (dataOffsetAndFlags >> 12) * 4; // in bytes
        this.flags = {
            ns: (dataOffsetAndFlags & 0x100) !== 0,
            cwr: (dataOffsetAndFlags & 0x80) !== 0,
            ece: (dataOffsetAndFlags & 0x40) !== 0,
            urg: (dataOffsetAndFlags & 0x20) !== 0,
            ack: (dataOffsetAndFlags & 0x10) !== 0,
            psh: (dataOffsetAndFlags & 0x08) !== 0,
            rst: (dataOffsetAndFlags & 0x04) !== 0,
            syn: (dataOffsetAndFlags & 0x02) !== 0,
            fin: (dataOffsetAndFlags & 0x01) !== 0
        };

        this.windowSize = view.getUint16(14);
        this.checksum = view.getUint16(16);
        this.urgentPointer = view.getUint16(18);

        // Parse options if present
        if (this.dataOffset > 20) {
            const optionsLength = this.dataOffset - 20;
            this.options = this.data.slice(20, 20 + optionsLength);
        }

        // Parse payload
        this.payload = this.data.slice(this.dataOffset);
    }

    public static createSegment(options: {
        sourcePort: number;
        destinationPort: number;
        sequenceNumber: number;
        acknowledgmentNumber?: number;
        flags: {
            fin?: boolean;
            syn?: boolean;
            rst?: boolean;
            psh?: boolean;
            ack?: boolean;
            urg?: boolean;
            ece?: boolean;
            cwr?: boolean;
            ns?: boolean;
        };
        windowSize?: number;
        urgentPointer?: number;
        payload?: Uint8Array;
    }): Uint8Array {
        const dataOffset = 5; // 5 * 32-bit words = 20 bytes (standard header)
        const headerLength = 20; // bytes

        // Calculate total length
        const payload = options.payload || new Uint8Array(0);
        const totalLength = headerLength + payload.length;

        // Create buffer
        const buffer = new ArrayBuffer(totalLength);
        const view = new DataView(buffer);

        // Set header fields
        view.setUint16(0, options.sourcePort);
        view.setUint16(2, options.destinationPort);
        view.setUint32(4, options.sequenceNumber);
        view.setUint32(8, options.acknowledgmentNumber || 0);

        // Data offset and flags
        let flagsByte = 0;
        flagsByte |= (options.flags.ns ? 0x01 : 0) << 8;
        flagsByte |= (options.flags.cwr ? 0x01 : 0) << 7;
        flagsByte |= (options.flags.ece ? 0x01 : 0) << 6;
        flagsByte |= (options.flags.urg ? 0x01 : 0) << 5;
        flagsByte |= (options.flags.ack ? 0x01 : 0) << 4;
        flagsByte |= (options.flags.psh ? 0x01 : 0) << 3;
        flagsByte |= (options.flags.rst ? 0x01 : 0) << 2;
        flagsByte |= (options.flags.syn ? 0x01 : 0) << 1;
        flagsByte |= (options.flags.fin ? 0x01 : 0);
        view.setUint16(12, (dataOffset << 12) | flagsByte);

        view.setUint16(14, options.windowSize || 65535); // Default window size
        view.setUint16(16, 0); // Checksum (calculated later)
        view.setUint16(18, options.urgentPointer || 0);

        // Copy payload
        const array = new Uint8Array(buffer);
        if (payload.length > 0) {
            array.set(payload, headerLength);
        }

        // Note: In a real implementation, you would calculate the checksum here
        // This requires a pseudo-header with IP information which we don't have

        return array;
    }

    public toString(): string {
        return `TCP Segment:
  Source Port: ${this.sourcePort}
  Destination Port: ${this.destinationPort}
  Sequence Number: ${this.sequenceNumber}
  Acknowledgment Number: ${this.acknowledgmentNumber}
  Data Offset: ${this.dataOffset} bytes
  Flags: ${JSON.stringify(this.flags)}
  Window Size: ${this.windowSize}
  Checksum: 0x${this.checksum.toString(16)}
  Urgent Pointer: ${this.urgentPointer}
  Payload Length: ${this.payload.length} bytes`;
    }
}

// Example usage:
// const ipv4Payload = new Uint8Array([...]); // Your IPv4 payload containing TCP segment
// const tcpSegment = new TCP(ipv4Payload);
// console.log(tcpSegment.toString());
```

## Important Notes:

1. This is a simplified implementation that handles basic TCP header parsing and construction.

2. A complete TCP implementation would need:
   - Connection state management (SYN, SYN-ACK, etc.)
   - Sequence number tracking
   - Flow control and congestion control
   - Retransmission mechanisms
   - Proper checksum calculation (requires IP pseudo-header)
   - Option handling (MSS, window scaling, etc.)

3. The checksum field is not calculated in this example because it requires IP header information (source/dest IP addresses) that we don't have in this scope.

4. For a production system, you would want to use Node.js's built-in `net` module or browser WebSockets rather than implementing TCP from scratch.

