# Implementing a SCIM Server in PHP with Slim Framework

Here's a comprehensive guide to building a SCIM (System for Cross-domain Identity Management) server using PHP and Slim as your router.

## 1. Setup the Project

First, create a new project and install required dependencies:

```bash
composer init
composer require slim/slim:"4.*"
composer require slim/psr7
composer require nyholm/psr7 nyholm/psr7-server
composer require ramsey/uuid
composer require firebase/php-jwt
```

## 2. Basic SCIM Server Structure

Create a basic SCIM server structure with these key files:

```
/scim-server
├── config/
│   └── scim.php
├── src/
│   ├── Controllers/
│   │   ├── UserController.php
│   │   └── GroupController.php
│   ├── Models/
│   │   ├── User.php
│   │   └── Group.php
│   └── Services/
│       ├── UserService.php
│       └── GroupService.php
├── public/
│   └── index.php
└── composer.json
```

## 3. Implement the SCIM Endpoints

### `public/index.php` - Main entry point

```php
<?php
use Psr\Http\Message\ResponseInterface as Response;
use Psr\Http\Message\ServerRequestInterface as Request;
use Slim\Factory\AppFactory;

require __DIR__ . '/../vendor/autoload.php';

$app = AppFactory::create();

// Add SCIM routes
require __DIR__ . '/../routes/scim.php';

$app->run();
```

### `routes/scim.php` - SCIM routes

```php
<?php
use Slim\Routing\RouteCollectorProxy;
use YourNamespace\Controllers\UserController;
use YourNamespace\Controllers\GroupController;

$app->group('/scim/v2', function (RouteCollectorProxy $group) {
    // Users endpoint
    $group->get('/Users', UserController::class . ':listUsers');
    $group->post('/Users', UserController::class . ':createUser');
    $group->get('/Users/{id}', UserController::class . ':getUser');
    $group->put('/Users/{id}', UserController::class . ':replaceUser');
    $group->patch('/Users/{id}', UserController::class . ':updateUser');
    $group->delete('/Users/{id}', UserController::class . ':deleteUser');

    // Groups endpoint
    $group->get('/Groups', GroupController::class . ':listGroups');
    $group->post('/Groups', GroupController::class . ':createGroup');
    $group->get('/Groups/{id}', GroupController::class . ':getGroup');
    $group->put('/Groups/{id}', GroupController::class . ':replaceGroup');
    $group->patch('/Groups/{id}', GroupController::class . ':updateGroup');
    $group->delete('/Groups/{id}', GroupController::class . ':deleteGroup');

    // Service provider config
    $group->get('/ServiceProviderConfig', function (Request $request, Response $response) {
        $config = [
            "schemas" => ["urn:ietf:params:scim:schemas:core:2.0:ServiceProviderConfig"],
            "patch" => ["supported" => true],
            "bulk" => ["supported" => false, "maxOperations" => 0, "maxPayloadSize" => 0],
            "filter" => ["supported" => true, "maxResults" => 200],
            "changePassword" => ["supported" => false],
            "sort" => ["supported" => false],
            "etag" => ["supported" => false],
            "authenticationSchemes" => [
                [
                    "name" => "OAuth Bearer Token",
                    "description" => "Authentication using OAuth Bearer Token",
                    "type" => "oauthbearertoken",
                    "primary" => true
                ]
            ]
        ];

        $response->getBody()->write(json_encode($config));
        return $response->withHeader('Content-Type', 'application/scim+json');
    });
});
```

## 4. User Controller Implementation

### `src/Controllers/UserController.php`

```php
<?php
namespace YourNamespace\Controllers;

use Psr\Http\Message\ResponseInterface as Response;
use Psr\Http\Message\ServerRequestInterface as Request;
use YourNamespace\Models\User;
use YourNamespace\Services\UserService;

class UserController
{
    private $userService;

    public function __construct(UserService $userService)
    {
        $this->userService = $userService;
    }

    public function listUsers(Request $request, Response $response): Response
    {
        $queryParams = $request->getQueryParams();
        $filter = $queryParams['filter'] ?? null;
        $startIndex = $queryParams['startIndex'] ?? 1;
        $count = $queryParams['count'] ?? 100;

        $users = $this->userService->getUsers($filter, $startIndex, $count);
        $totalResults = $this->userService->countUsers($filter);

        $result = [
            "schemas" => ["urn:ietf:params:scim:api:messages:2.0:ListResponse"],
            "totalResults" => $totalResults,
            "startIndex" => $startIndex,
            "itemsPerPage" => count($users),
            "Resources" => $users
        ];

        $response->getBody()->write(json_encode($result));
        return $response->withHeader('Content-Type', 'application/scim+json');
    }

    public function createUser(Request $request, Response $response): Response
    {
        $data = json_decode($request->getBody()->getContents(), true);

        // Validate schema
        if (!isset($data['schemas']) || !in_array('urn:ietf:params:scim:schemas:core:2.0:User', $data['schemas'])) {
            return $this->errorResponse($response, 400, "invalidSyntax", "Request must include the User schema.");
        }

        try {
            $user = $this->userService->createUser($data);

            $response->getBody()->write(json_encode($user));
            return $response
                ->withStatus(201)
                ->withHeader('Content-Type', 'application/scim+json')
                ->withHeader('Location', '/scim/v2/Users/' . $user['id']);
        } catch (\Exception $e) {
            return $this->errorResponse($response, 400, "invalidValue", $e->getMessage());
        }
    }

    public function getUser(Request $request, Response $response, array $args): Response
    {
        $userId = $args['id'];

        try {
            $user = $this->userService->getUser($userId);

            if (!$user) {
                return $this->errorResponse($response, 404, "notFound", "User not found.");
            }

            $response->getBody()->write(json_encode($user));
            return $response->withHeader('Content-Type', 'application/scim+json');
        } catch (\Exception $e) {
            return $this->errorResponse($response, 500, "internalError", $e->getMessage());
        }
    }

    // Implement other methods (replaceUser, updateUser, deleteUser) similarly

    private function errorResponse(Response $response, int $status, string $scimType, string $detail): Response
    {
        $error = [
            "schemas" => ["urn:ietf:params:scim:api:messages:2.0:Error"],
            "status" => (string)$status,
            "scimType" => $scimType,
            "detail" => $detail
        ];

        $response->getBody()->write(json_encode($error));
        return $response
            ->withStatus($status)
            ->withHeader('Content-Type', 'application/scim+json');
    }
}
```

## 5. User Service Implementation

### `src/Services/UserService.php`

```php
<?php
namespace YourNamespace\Services;

use Ramsey\Uuid\Uuid;
use YourNamespace\Models\User;

class UserService
{
    private $userModel;

    public function __construct(User $userModel)
    {
        $this->userModel = $userModel;
    }

    public function getUsers(?string $filter, int $startIndex, int $count): array
    {
        // Implement filtering logic based on SCIM filter syntax
        // For simplicity, we'll ignore the filter in this example

        $users = $this->userModel->getPaginated($startIndex, $count);

        return array_map(function($user) {
            return $this->formatUserResponse($user);
        }, $users);
    }

    public function countUsers(?string $filter): int
    {
        return $this->userModel->countAll();
    }

    public function getUser(string $id): ?array
    {
        $user = $this->userModel->findById($id);

        if (!$user) {
            return null;
        }

        return $this->formatUserResponse($user);
    }

    public function createUser(array $data): array
    {
        // Validate required fields
        if (empty($data['userName'])) {
            throw new \InvalidArgumentException("userName is required.");
        }

        // Generate ID if not provided
        if (empty($data['id'])) {
            $data['id'] = Uuid::uuid4()->toString();
        }

        // Set meta information
        $now = (new \DateTime())->format('c');
        $data['meta'] = [
            "resourceType" => "User",
            "created" => $now,
            "lastModified" => $now,
            "location" => "/scim/v2/Users/" . $data['id'],
            "version" => "W/\"" . md5($now) . "\""
        ];

        // Save to database
        $userId = $this->userModel->create($data);

        return $this->formatUserResponse($this->userModel->findById($userId));
    }

    private function formatUserResponse(array $user): array
    {
        // Transform database fields to SCIM format
        return [
            "schemas" => ["urn:ietf:params:scim:schemas:core:2.0:User"],
            "id" => $user['id'],
            "userName" => $user['username'],
            "name" => [
                "givenName" => $user['first_name'],
                "familyName" => $user['last_name']
            ],
            "emails" => [
                [
                    "value" => $user['email'],
                    "primary" => true
                ]
            ],
            "active" => (bool)$user['active'],
            "meta" => [
                "resourceType" => "User",
                "created" => $user['created_at'],
                "lastModified" => $user['updated_at'],
                "location" => "/scim/v2/Users/" . $user['id'],
                "version" => $user['version']
            ]
        ];
    }
}
```

## 6. Authentication Middleware

Add authentication middleware to protect your SCIM endpoints:

```php
<?php
namespace YourNamespace\Middleware;

use Psr\Http\Message\ResponseInterface as Response;
use Psr\Http\Message\ServerRequestInterface as Request;
use Psr\Http\Server\MiddlewareInterface;
use Psr\Http\Server\RequestHandlerInterface as RequestHandler;
use Firebase\JWT\JWT;
use Firebase\JWT\Key;

class ScimAuthMiddleware implements MiddlewareInterface
{
    private $secretKey;

    public function __construct(string $secretKey)
    {
        $this->secretKey = $secretKey;
    }

    public function process(Request $request, RequestHandler $handler): Response
    {
        $authHeader = $request->getHeader('Authorization');

        if (empty($authHeader) || !preg_match('/Bearer\s(\S+)/', $authHeader[0], $matches)) {
            return $this->unauthorizedResponse();
        }

        $token = $matches[1];

        try {
            $decoded = JWT::decode($token, new Key($this->secretKey, 'HS256'));

            // You can add additional validation here (check scopes, etc.)

            return $handler->handle($request);
        } catch (\Exception $e) {
            return $this->unauthorizedResponse($e->getMessage());
        }
    }

    private function unauthorizedResponse(string $detail = 'Authentication required'): Response
    {
        $response = new \Slim\Psr7\Response();
        $error = [
            "schemas" => ["urn:ietf:params:scim:api:messages:2.0:Error"],
            "status" => "401",
            "detail" => $detail
        ];

        $response->getBody()->write(json_encode($error));
        return $response
            ->withStatus(401)
            ->withHeader('Content-Type', 'application/scim+json')
            ->withHeader('WWW-Authenticate', 'Bearer realm="SCIM API"');
    }
}
```

