<body>
    <div class="container">
        <h1>Sprite Editor</h1>

        <div class="editor-container">
            <div class="canvas-container">
                <canvas id="gridCanvas"></canvas>
            </div>

            <div class="tools">
                <div class="tool-buttons">
                    <button id="pencilTool" class="active">✏️ Pencil</button>
                    <button id="fillTool">🎨 Fill</button>
                    <button id="rectTool">⬜ Rectangle</button>
                    <button id="eraserTool">🧽 Eraser</button>
                </div>

                <div class="slider-container">
                    <label for="zoomSlider">Zoom: <span id="zoomValue">400%</span></label>
                    <input type="range" id="zoomSlider" min="100" max="2000" value="400" step="100">
                </div>

                <div class="slider-container">
                    <label for="gridSize">Grid Size: <span id="gridSizeValue">16x16</span></label>
                    <input type="range" id="gridSize" min="4" max="64" value="16" step="4">
                </div>

                <div>
                    <label>Current Color:</label>
                    <div id="currentColor" class="color" style="background-color: #000000;"></div>
                </div>

                <div class="palette" id="palette">
                    <!-- Colors will be added here by JavaScript -->
                </div>

                <div class="save-load">
                    <button id="saveBtn">💾 Save</button>
                    <button id="loadBtn">📂 Load</button>
                    <button id="clearBtn">🗑️ Clear</button>
                </div>
            </div>
        </div>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', function() {
            // Canvas setup
            const canvas = document.getElementById('gridCanvas');
            const ctx = canvas.getContext('2d');

            // Editor state
            let gridSize = 16;
            let zoom = 4;
            let currentColor = '#000000';
            let isDrawing = false;
            let currentTool = 'pencil';
            let spriteData = [];

            // Initialize default color palette
            const defaultPalette = [
                '#000000', '#FFFFFF', '#FF0000', '#00FF00', '#0000FF', 
                '#FFFF00', '#FF00FF', '#00FFFF', '#808080', '#C0C0C0',
                '#800000', '#008000', '#000080', '#808000', '#800080',
                '#008080', '#FFA500', '#A52A2A', '#FFC0CB', '#ADD8E6'
            ];

            // DOM elements
            const zoomSlider = document.getElementById('zoomSlider');
            const zoomValue = document.getElementById('zoomValue');
            const gridSizeSlider = document.getElementById('gridSize');
            const gridSizeValue = document.getElementById('gridSizeValue');
            const currentColorDisplay = document.getElementById('currentColor');
            const paletteContainer = document.getElementById('palette');
            const pencilTool = document.getElementById('pencilTool');
            const fillTool = document.getElementById('fillTool');
            const rectTool = document.getElementById('rectTool');
            const eraserTool = document.getElementById('eraserTool');
            const saveBtn = document.getElementById('saveBtn');
            const loadBtn = document.getElementById('loadBtn');
            const clearBtn = document.getElementById('clearBtn');

            // Initialize the editor
            function init() {
                createPalette();
                initializeSpriteData();
                updateCanvasSize();
                drawGrid();

                // Set up event listeners
                canvas.addEventListener('mousedown', startDrawing);
                canvas.addEventListener('mousemove', draw);
                canvas.addEventListener('mouseup', stopDrawing);
                canvas.addEventListener('mouseout', stopDrawing);

                zoomSlider.addEventListener('input', updateZoom);
                gridSizeSlider.addEventListener('input', updateGridSize);

                pencilTool.addEventListener('click', () => setTool('pencil'));
                fillTool.addEventListener('click', () => setTool('fill'));
                rectTool.addEventListener('click', () => setTool('rectangle'));
                eraserTool.addEventListener('click', () => setTool('eraser'));

                saveBtn.addEventListener('click', saveSprite);
                loadBtn.addEventListener('click', loadSprite);
                clearBtn.addEventListener('click', clearCanvas);
            }

            // Create color palette
            function createPalette() {
                paletteContainer.innerHTML = '';
                defaultPalette.forEach(color => {
                    const colorDiv = document.createElement('div');
                    colorDiv.className = 'color';
                    colorDiv.style.backgroundColor = color;
                    colorDiv.addEventListener('click', () => {
                        currentColor = color;
                        currentColorDisplay.style.backgroundColor = color;
                        document.querySelectorAll('.color').forEach(el => el.classList.remove('selected'));
                        colorDiv.classList.add('selected');
                    });
                    paletteContainer.appendChild(colorDiv);

                    // Select first color by default
                    if (color === '#000000') {
                        colorDiv.classList.add('selected');
                    }
                });
            }

            // Initialize sprite data array
            function initializeSpriteData() {
                spriteData = [];
                for (let y = 0; y < gridSize; y++) {
                    const row = [];
                    for (let x = 0; x < gridSize; x++) {
                        row.push('#FFFFFF'); // White by default
                    }
                    spriteData.push(row);
                }
            }

            // Update canvas size based on grid size and zoom
            function updateCanvasSize() {
                canvas.width = gridSize * zoom;
                canvas.height = gridSize * zoom;
                drawGrid();
            }

            // Update zoom level
            function updateZoom() {
                zoom = parseInt(zoomSlider.value) / 100;
                zoomValue.textContent = `${zoom * 100}%`;
                updateCanvasSize();
            }

            // Update grid size
            function updateGridSize() {
                gridSize = parseInt(gridSizeSlider.value);
                gridSizeValue.textContent = `${gridSize}x${gridSize}`;
                initializeSpriteData();
                updateCanvasSize();
            }

            // Set current tool
            function setTool(tool) {
                currentTool = tool;
                pencilTool.classList.remove('active');
                fillTool.classList.remove('active');
                rectTool.classList.remove('active');
                eraserTool.classList.remove('active');

                switch (tool) {
                    case 'pencil': pencilTool.classList.add('active'); break;
                    case 'fill': fillTool.classList.add('active'); break;
                    case 'rectangle': rectTool.classList.add('active'); break;
                    case 'eraser': eraserTool.classList.add('active'); break;
                }
            }

            // Drawing functions
            function startDrawing(e) {
                isDrawing = true;
                const pos = getCursorPosition(e);
                if (currentTool === 'rectangle') {
                    // For rectangle, we'll store the start position
                    startX = pos.x;
                    startY = pos.y;
                } else {
                    drawAtPosition(pos.x, pos.y);
                }
            }

            function draw(e) {
                if (!isDrawing) return;
                const pos = getCursorPosition(e);

                if (currentTool === 'rectangle') {
                    // For rectangle, we'll draw a preview
                    drawGrid(); // Clear preview
                    drawRectangle(startX, startY, pos.x, pos.y, currentColor, true);
                } else {
                    drawAtPosition(pos.x, pos.y);
                }
            }

            function stopDrawing(e) {
                if (!isDrawing) return;

                if (currentTool === 'rectangle') {
                    const pos = getCursorPosition(e);
                    drawRectangle(startX, startY, pos.x, pos.y, currentColor, false);
                }

                isDrawing = false;
            }

            function getCursorPosition(e) {
                const rect = canvas.getBoundingClientRect();
                const x = Math.floor((e.clientX - rect.left) / zoom);
                const y = Math.floor((e.clientY - rect.top) / zoom);
                return { x, y };
            }

            function drawAtPosition(x, y) {
                if (x < 0 || x >= gridSize || y < 0 || y >= gridSize) return;

                if (currentTool === 'eraser') {
                    spriteData[y][x] = '#FFFFFF'; // Erase to white
                } else if (currentTool === 'fill') {
                    floodFill(x, y, spriteData[y][x], currentColor);
                } else {
                    spriteData[y][x] = currentTool === 'pencil' ? currentColor : '#FFFFFF';
                }

                drawGrid();
            }

            // Flood fill algorithm
            function floodFill(x, y, targetColor, replacementColor) {
                if (targetColor === replacementColor) return;
                if (x < 0 || x >= gridSize || y < 0 || y >= gridSize) return;
                if (spriteData[y][x] !== targetColor) return;

                spriteData[y][x] = replacementColor;

                floodFill(x + 1, y, targetColor, replacementColor);
                floodFill(x - 1, y, targetColor, replacementColor);
                floodFill(x, y + 1, targetColor, replacementColor);
                floodFill(x, y - 1, targetColor, replacementColor);
            }

            // Draw rectangle (preview or final)
            function drawRectangle(x1, y1, x2, y2, color, isPreview) {
                // Ensure x1 <= x2 and y1 <= y2
                const startX = Math.min(x1, x2);
                const endX = Math.max(x1, x2);
                const startY = Math.min(y1, y2);
                const endY = Math.max(y1, y2);

                if (isPreview) {
                    ctx.strokeStyle = color;
                    ctx.lineWidth = 1;
                    ctx.strokeRect(
                        startX * zoom, 
                        startY * zoom, 
                        (endX - startX + 1) * zoom, 
                        (endY - startY + 1) * zoom
                    );
                } else {
                    // Apply the rectangle to the sprite data
                    for (let y = startY; y <= endY; y++) {
                        for (let x = startX; x <= endX; x++) {
                            if (x >= 0 && x < gridSize && y >= 0 && y < gridSize) {
                                spriteData[y][x] = color;
                            }
                        }
                    }
                    drawGrid();
                }
            }

            // Draw the grid based on sprite data
            function drawGrid() {
                ctx.clearRect(0, 0, canvas.width, canvas.height);

                // Draw the pixels
                for (let y = 0; y < gridSize; y++) {
                    for (let x = 0; x < gridSize; x++) {
                        ctx.fillStyle = spriteData[y][x];
                        ctx.fillRect(x * zoom, y * zoom, zoom, zoom);
                    }
                }

                // Draw grid lines
                ctx.strokeStyle = '#CCCCCC';
                ctx.lineWidth = 1;

                for (let x = 0; x <= gridSize; x++) {
                    ctx.beginPath();
                    ctx.moveTo(x * zoom, 0);
                    ctx.lineTo(x * zoom, gridSize * zoom);
                    ctx.stroke();
                }

                for (let y = 0; y <= gridSize; y++) {
                    ctx.beginPath();
                    ctx.moveTo(0, y * zoom);
                    ctx.lineTo(gridSize * zoom, y * zoom);
                    ctx.stroke();
                }
            }

            // Save sprite as JSON
            function saveSprite() {
                const sprite = {
                    gridSize: gridSize,
                    data: spriteData
                };

                const dataStr = JSON.stringify(sprite);
                const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);

                const exportName = 'sprite.json';

                const linkElement = document.createElement('a');
                linkElement.setAttribute('href', dataUri);
                linkElement.setAttribute('download', exportName);
                linkElement.click();
            }

            // Load sprite from file
            function loadSprite() {
                const input = document.createElement('input');
                input.type = 'file';
                input.accept = '.json';

                input.onchange = e => {
                    const file = e.target.files[0];
                    if (!file) return;

                    const reader = new FileReader();
                    reader.onload = event => {
                        try {
                            const loadedSprite = JSON.parse(event.target.result);
                            if (loadedSprite.gridSize && loadedSprite.data) {
                                gridSize = loadedSprite.gridSize;
                                spriteData = loadedSprite.data;
                                gridSizeSlider.value = gridSize;
                                gridSizeValue.textContent = `${gridSize}x${gridSize}`;
                                updateCanvasSize();
                            }
                        } catch (error) {
                            alert('Error loading sprite: ' + error.message);
                        }
                    };
                    reader.readAsText(file);
                };

                input.click();
            }

            // Clear the canvas
            function clearCanvas() {
                if (confirm('Are you sure you want to clear the canvas?')) {
                    for (let y = 0; y < gridSize; y++) {
                        for (let x = 0; x < gridSize; x++) {
                            spriteData[y][x] = '#FFFFFF';
                        }
                    }
                    drawGrid();
                }
            }

            // Initialize the editor
            init();
        });
    </script>
</body>
</html>
```

