# Action System Implementation

I'll design a flexible Action class that can handle various character interactions through a data-driven configuration system. Here's my implementation:

```python
import math

class Action:
    """
    A data-driven action system for character interactions.
    Configured through an action dictionary with these possible fields:

    Required:
    - type: The action type (e.g., "damage", "heal", "composite")

    Common fields (type-dependent):
    - target: "self", "other", or "both"
    - amount: Fixed amount or formula for calculation
    - formula: Mathematical expression using actor/target properties
    - effects: List of sub-actions for composite actions

    Example configurations:
    1. Deal fixed damage to target:
        {"type": "damage", "target": "other", "amount": 10}

    2. Heal self:
        {"type": "heal", "target": "self", "amount": 15}

    3. Life leech (damage target and heal actor by portion):
        {"type": "composite", "effects": [
            {"type": "damage", "target": "other", "formula": "actor.damage * 1.2"},
            {"type": "heal", "target": "self", "formula": "result[0] * 0.3"}
        ]}

    4. Sacrifice (damage based on portion of actor's health):
        {"type": "composite", "effects": [
            {"type": "damage", "target": "other", "formula": "actor.hp * 0.3"},
            {"type": "damage", "target": "self", "formula": "actor.hp * 0.1"}
        ]}
    """

    def __init__(self, action_config):
        self.config = action_config
        self.type = action_config.get("type", "damage")
        self.target = action_config.get("target", "other")
        self.amount = action_config.get("amount", 0)
        self.formula = action_config.get("formula", None)
        self.effects = [Action(effect) for effect in action_config.get("effects", [])]

    def execute(self, actor, target=None):
        """
        Execute the action with the given actor and optional target.
        Returns a dictionary with results and any side effects.
        """
        if self.type == "composite":
            return self._execute_composite(actor, target)
        elif self.type == "damage":
            return self._execute_damage(actor, target)
        elif self.type == "heal":
            return self._execute_heal(actor, target)
        else:
            raise ValueError(f"Unknown action type: {self.type}")

    def _execute_composite(self, actor, target):
        results = []
        for effect in self.effects:
            result = effect.execute(actor, target)
            results.append(result)

            # Make previous results available to subsequent formulas
            if hasattr(actor, "last_action_results"):
                actor.last_action_results = results
            if target and hasattr(target, "last_action_results"):
                target.last_action_results = results

        return {"type": "composite", "results": results}

    def _execute_damage(self, actor, target):
        amount = self._calculate_amount(actor, target)

        if self.target == "self":
            actor.hp -= amount
            return {"type": "damage", "target": "self", "amount": amount, "hp_remaining": actor.hp}
        elif self.target == "other" and target:
            target.hp -= amount
            return {"type": "damage", "target": "other", "amount": amount, "hp_remaining": target.hp}
        elif self.target == "both" and target:
            actor.hp -= amount
            target.hp -= amount
            return {
                "type": "damage",
                "target": "both",
                "amount": amount,
                "actor_hp": actor.hp,
                "target_hp": target.hp
            }
        else:
            raise ValueError("Invalid damage target configuration")

    def _execute_heal(self, actor, target):
        amount = self._calculate_amount(actor, target)

        if self.target == "self":
            actor.hp = min(actor.hp + amount, actor.max_hp if hasattr(actor, "max_hp") else float('inf'))
            return {"type": "heal", "target": "self", "amount": amount, "hp_remaining": actor.hp}
        elif self.target == "other" and target:
            target.hp = min(target.hp + amount, target.max_hp if hasattr(target, "max_hp") else float('inf'))
            return {"type": "heal", "target": "other", "amount": amount, "hp_remaining": target.hp}
        else:
            raise ValueError("Invalid heal target configuration")

    def _calculate_amount(self, actor, target):
        """Calculate the action amount using either fixed amount or formula"""
        if self.formula:
            # Create a safe evaluation environment
            local_vars = {
                'actor': actor,
                'target': target,
                'math': math,
                'result': getattr(actor, 'last_action_results', []) + getattr(target, 'last_action_results', [])
            }

            try:
                return eval(self.formula, {"__builtins__": None}, local_vars)
            except Exception as e:
                raise ValueError(f"Error evaluating formula '{self.formula}': {str(e)}")
        return self.amount
```

## Example Usage

Here's how you would use this system with your Character class:

```python
# Example character data
player_data = {
    "name": "Hero",
    "hp": 100,
    "damage": 15,
    "max_hp": 100
}

enemy_data = {
    "name": "Goblin",
    "hp": 50,
    "damage": 8,
    "max_hp": 50
}

player = Character(player_data)
enemy = Character(enemy_data)

# Define some actions
basic_attack = Action({
    "type": "damage",
    "target": "other",
    "amount": 10
})

heal_self = Action({
    "type": "heal",
    "target": "self",
    "amount": 15
})

life_leech = Action({
    "type": "composite",
    "effects": [
        {"type": "damage", "target": "other", "formula": "actor.damage * 1.2"},
        {"type": "heal", "target": "self", "formula": "result[0]['amount'] * 0.3"}
    ]
})

sacrifice = Action({
    "type": "composite",
    "effects": [
        {"type": "damage", "target": "other", "formula": "actor.hp * 0.3"},
        {"type": "damage", "target": "self", "formula": "actor.hp * 0.1"}
    ]
})

# Execute actions
print("Player HP:", player.hp, "Enemy HP:", enemy.hp)

# Basic attack
result = basic_attack.execute(player, enemy)
print(f"{player.name} attacks {enemy.name} for {result['amount']} damage!")
print("Enemy HP:", enemy.hp)

# Life leech
result = life_leech.execute(player, enemy)
damage = result['results'][0]['amount']
heal = result['results'][1]['amount']
print(f"{player.name} life leeches {enemy.name} for {damage} damage!")
print(f"{player.name} heals for {heal} health!")
print("Player HP:", player.hp, "Enemy HP:", enemy.hp)

# Sacrifice attack
result = sacrifice.execute(player, enemy)
damage_to_enemy = result['results'][0]['amount']
damage_to_self = result['results'][1]['amount']
print(f"{player.name} sacrifices {damage_to_self} HP to deal {damage_to_enemy} damage!")
print("Player HP:", player.hp, "Enemy HP:", enemy.hp)
```

## Key Features

1. **Data-Driven Design**: All actions are configured through dictionaries that can be loaded from JSON/YAML files.

2. **Flexible Targeting**: Supports "self", "other", or "both" as targets.

3. **Formula Support**: Uses Python expressions with access to:
   - Actor properties (`actor.hp`, `actor.damage`, etc.)
   - Target properties (when applicable)
   - Math module for calculations
   - Previous action results (for composite actions)

4. **Composite Actions**: Combine multiple effects into a single action (like life leech or sacrifice).

5. **Extensible**: New action types can be added by extending the `execute` method.

6. **Result Tracking**: Returns detailed information about each action's effects.

This implementation provides a powerful configuration system while maintaining security (using a restricted eval environment) and flexibility for your game's needs.

# Using @tanstack/vue-query with Pinia for Session Data

Here's how to fetch data from `/get_session` using `@tanstack/vue-query` (formerly react-query) and update specific keys in a Pinia store:

## 1. First, set up your Pinia store

```typescript
// stores/session.ts
import { defineStore } from 'pinia'

export const useSessionStore = defineStore('session', {
  state: () => ({
    userId: null as number | null,
    userName: '' as string,
    permissions: [] as string[],
    // other session-related state
  }),
  actions: {
    updateSession(payload: { userId?: number; userName?: string; permissions?: string[] }) {
      if (payload.userId !== undefined) this.userId = payload.userId
      if (payload.userName !== undefined) this.userName = payload.userName
      if (payload.permissions !== undefined) this.permissions = payload.permissions
      // update other fields as needed
    },
  },
})
```

## 2. Create a composable for the query

```typescript
// composables/useSession.ts
import { useQuery } from '@tanstack/vue-query'
import { useSessionStore } from '@/stores/session'

export function useSession() {
  const sessionStore = useSessionStore()

  return useQuery({
    queryKey: ['session'],
    queryFn: async () => {
      const response = await fetch('/get_session')
      if (!response.ok) {
        throw new Error('Failed to fetch session data')
      }
      return response.json()
    },
    onSuccess: (data) => {
      // Select only the keys we want to update in the store
      sessionStore.updateSession({
        userId: data.user_id,
        userName: data.username,
        permissions: data.permissions,
        // add other fields as needed
      })
    },
    // Optional: configure caching, retry behavior, etc.
    staleTime: 30 * 60 * 1000, // 30 minutes
    retry: 2,
  })
}
```

## 3. Use the composable in your component

```vue
<!-- components/SessionLoader.vue -->
<script setup lang="ts">
import { useSession } from '@/composables/useSession'

const { isLoading, isError, error } = useSession()
</script>

<template>
  <div v-if="isLoading">Loading session...</div>
  <div v-else-if="isError">Error: {{ error }}</div>
  <!-- When successful, the data is already in your Pinia store -->
</template>
```

## 4. Access the session data anywhere using the Pinia store

```vue
<!-- components/SomeOtherComponent.vue -->
<script setup lang="ts">
import { useSessionStore } from '@/stores/session'

const session = useSessionStore()
</script>

<template>
  <div v-if="session.userId">
    Welcome, {{ session.userName }}!
  </div>
</template>
```

## Key Points:

1. **Separation of concerns**: The query handles data fetching, while Pinia manages the global state.
2. **Selective updates**: The `onSuccess` callback lets you pick exactly which fields to update in the store.
3. **Type safety**: Use TypeScript interfaces to define your session data shape.
4. **Error handling**: The query provides built-in error states you can use in your UI.
5. **Performance**: Configure caching options like `staleTime` to optimize performance.

